{
  "probability": 0.64,
  "range_low": 0.58,
  "range_high": 0.70,
  "summary": [
    "Anchor on historical Mediterranean fatalities and the February 2026 pace (~606 deaths by late February) to establish a neutral prior around 0.60 before March–April updates.",
    "Near-term window (March–April, with possible spill into May) could plausibly push the total to 1,000 deaths if the pace remains elevated.",
    "Factors include harsh weather, rising departures in early 2026, and high-profile coverage that elevate perceived risk; SAR capacity and policy changes could dampen the outcome.",
    "Calibrated Bayesian update yields a posterior around 0.64, with acknowledged data gaps and potential correlations among updates."
  ],
  "confidence": "low",
  "narrative": "Starting from a historical base-rate anchor, the observed high early-2026 pace and upcoming March–April window provide a plausible path to surpass 1,000 Mediterranean deaths by May, though uncertainty remains due to data gaps and potential countervailing factors.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Midpoint of the historical annual Mediterranean fatality range (~2,000–2,500 per year) combined with the observed ~606 deaths by late February 2026 to establish a neutral prior before case-specific updates."
    },
    "factor_updates": [
      {
        "factor": "Near-term pace of fatalities (Feb–Mar/Apr 2026)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "With 606 deaths by late February, sustained above-average monthly pace into March–April would increase the likelihood of crossing 1,000 by May."
      },
      {
        "factor": "Remaining calendar window (March–April, possibly May)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Two to three months remain, offering substantial potential to accumulate additional deaths if conditions remain adverse."
      },
      {
        "factor": "Publicized record pace and media/UN emphasis",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Intense coverage and warnings reflect elevated hazard and can correlate with higher fatality risk."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Expanded SAR capacity or policy changes restricting crossings could reduce deaths, pulling the total down."
      },
      {
        "factor": "Potential for a major single shipwreck",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A single catastrophic event could add hundreds of deaths quickly, significantly boosting totals."
      }
    ],
    "synthesis_rationale": "The posterior of 0.64 results from a moderate elevation above a 0.60 anchor due to nearby-term momentum and high-risk indicators, partially offset by SAR/policy mitigations. Correlated factors and data gaps justify the modest confidence rating."
  }
}

{
  "probability": 0.64,
  "range_low": 0.53,
  "range_high": 0.75,
  "summary": [
    "Posterior probability: 0.64 (64%) of recording at least 1,000 Mediterranean deaths in 2026 before May.",
    "Anchor probability from historical Mediterranean fatalities with a plausible base-rate around 0.40, updated upward by recent pace and remaining calendar window.",
    "Key updates: pace through February (≈606 deaths) and remaining March–April raise risk; potential for a major shipwreck could push totals higher; SAR capacity and policy changes could dampen or amplify outcomes.",
    "Overall uncertainty remains due to data gaps, undercounts, and possible shifts in crossing patterns or weather."
  ],
  "confidence": "low",
  "narrative": "Starting from a historically informed base-rate, the unusually high early-2026 death pace and the remaining months raise the odds of >1,000 deaths by May to about 64%, but data gaps and possible policy or SAR changes keep the forecast uncertain."
  ,
  "justification": {
    "anchor": {
      "probability": 0.40,
      "basis": "Reference-class anchor based on historical IOM Mediterranean fatalities (~2,000–2,500 per year) and the long-run monthly average (~180 deaths/month); the priors imply a plausible starting probability around 0.40 for reaching 1,000 by end-April."
    },
    "factor_updates": [
      {
        "factor": "Near-term pace of fatalities (Feb–Mar/Apr 2026)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 24 indicate a record-pace start; if March–April stay above average, the chance of crossing 1,000 by end-April rises."
      },
      {
        "factor": "Remaining calendar window (March–April, spill into May)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Two to three months left can add hundreds of deaths if conditions remain adverse."
      },
      {
        "factor": "Unusually high early-2026 pace data reliability and potential undercount",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Underreporting and data gaps could imply higher true toll, nudging totals upward."
      },
      {
        "factor": "SAR capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Expanded SAR could save lives, dampening mortality; tighter policies could worsen it."
      },
      {
        "factor": "Major shipwreck risk (single event)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A single catastrophe could push totals sharply higher in a short window."
      },
      {
        "factor": "Seasonal weather conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Harsh spring seas increase hazards on crossing routes."
      },
      {
        "factor": "Data gaps and potential undercount of fatalities",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Missing data could understate current counts, raising the eventual total."
      }
    ],
    "synthesis_rationale": "Starts with a 0.40 anchor based on historical annual totals; each factor update contributes a directional nudge with plausible magnitude. The combination of elevated pace, remaining months, and potential shock events produces a posterior around 0.64, while SAR improvements, policy changes, and data gaps introduce uncertainty and potential countervailing shifts."
  }
}

{
  "probability": 0.33,
  "range_low": 0.25,
  "range_high": 0.45,
  "summary": [
    "Historical annual Mediterranean fatalities are in the low-to-mid thousands; 606 deaths by late February 2026 keep the end-April total plausible but not guaranteed.",
    "To reach 1,000 by end-April, March–April would need a pace above the historical monthly average, making the event possible but not highly likely.",
    "Upsides include the unusually high early-2026 pace and potential for a major single wreck; downsides include improved SAR capacity and policy measures that could suppress crossings.",
    "Overall, the calibrated probability is modest with notable uncertainty and tail risk."
  ],
  "confidence": "low",
  "narrative": "By late Feb 2026, mortality pace on the Mediterranean was unusually high. While a 1,000-death tally by end-April is possible, it requires sustained above-average fatalities or a catastrophic event, and countervailing SAR/policy factors reduce confidence in that outcome.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class uses historical annual Mediterranean fatalities (2,000–2,500) and current pace (~606 by late Feb 2026) to anchor a base-case around one-third probability for reaching 1,000 by end-April."
    },
    "factor_updates": [
      {
        "factor": "Near-term pace of fatalities (Feb–Mar/Apr 2026)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 24; to hit 1,000 by end-April requires roughly 394 more across two months. A continued elevated pace would increase odds; otherwise, the odds stay low."
      },
      {
        "factor": "Remaining calendar window (March–April)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Two months remain; more opportunities for deaths than in the baseline; raises probability modestly."
      },
      {
        "factor": "Unverified reporting gaps / missing data",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "IOM data are incomplete; true toll could exceed reported counts, potentially pushing toward 1,000."
      },
      {
        "factor": "Rescue capacity expansion (SAR)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Increased SAR capacity reduces fatalities by enabling more rescues; lowers the risk of hitting 1,000 by end-April."
      },
      {
        "factor": "Policy/regulatory restrictions limiting SAR / crossing routes",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Crackdowns and reduced NGO presence can reduce rescue coverage and potentially raise fatalities."
      },
      {
        "factor": "Major single shipwreck risk",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A single catastrophic event could add hundreds of deaths quickly, disproportionately affecting the total."
      }
    ],
    "synthesis_rationale": "We start from anchor ~0.35 and apply each factor as a delta with magnitude; the net effect is a modest upward tilt from the anchor due to pace and window, tempered by SAR improvements and policy constraints; tail risk from a large wreck lifts the probability in the upper tail. Given the combination, a probability in the low- to mid-30s% with an uncertainty range roughly 25%–45% is plausible, acknowledging data gaps and possible shocks."
  }
}
